CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE app_config (id boolean PRIMARY KEY DEFAULT true CHECK(id), data jsonb NOT NULL);
CREATE TABLE users (id text PRIMARY KEY, data jsonb NOT NULL, event_cursor bigint NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX users_handle ON users ((data->>'handle'));
CREATE TABLE places (id text PRIMARY KEY, data jsonb NOT NULL);
CREATE TABLE items (id text PRIMARY KEY, data jsonb NOT NULL, owner_id text GENERATED ALWAYS AS (data->>'ownerId') STORED REFERENCES users(id));
CREATE TABLE item_unavailable_intervals (item_id text NOT NULL REFERENCES items(id), period tstzrange NOT NULL, EXCLUDE USING gist (item_id WITH =, period WITH &&));
CREATE TABLE sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), token_hash text UNIQUE NOT NULL, csrf_token text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE rental_requests (id text PRIMARY KEY, data jsonb NOT NULL, requester_id text GENERATED ALWAYS AS (data->>'requesterId') STORED REFERENCES users(id), latest_turn_id text);
CREATE INDEX requests_requester ON rental_requests(requester_id, id);
CREATE TABLE request_need_revisions (request_id text REFERENCES rental_requests(id), revision integer NOT NULL, need jsonb NOT NULL, created_at timestamptz NOT NULL, PRIMARY KEY (request_id, revision));
CREATE TABLE summary_confirmations (id bigserial PRIMARY KEY, request_id text REFERENCES rental_requests(id), need_revision integer NOT NULL, actor_user_id text REFERENCES users(id), confirmed_at timestamptz NOT NULL);
CREATE TABLE pricing_quotes (id text PRIMARY KEY, data jsonb NOT NULL, request_id text GENERATED ALWAYS AS (data->>'requestId') STORED REFERENCES rental_requests(id));
CREATE INDEX quotes_scope ON pricing_quotes (request_id, (data->>'negotiationId'), (data->>'conditionsHash'));
CREATE TABLE fee_cache (conditions_hash text PRIMARY KEY, data jsonb NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE candidates (id text PRIMARY KEY, data jsonb NOT NULL, request_id text GENERATED ALWAYS AS (data->>'requestId') STORED REFERENCES rental_requests(id), UNIQUE (request_id, id));
CREATE TABLE negotiations (id text PRIMARY KEY, data jsonb NOT NULL, request_id text GENERATED ALWAYS AS (data->>'requestId') STORED REFERENCES rental_requests(id), item_id text GENERATED ALWAYS AS (data->>'itemId') STORED REFERENCES items(id), owner_id text GENERATED ALWAYS AS (data->>'ownerId') STORED REFERENCES users(id), UNIQUE(request_id,item_id));
CREATE INDEX negotiations_owner ON negotiations(owner_id,id);
CREATE TABLE terms_revisions (negotiation_id text REFERENCES negotiations(id), revision integer NOT NULL, terms jsonb NOT NULL, actor_user_id text REFERENCES users(id), reason text, created_at timestamptz NOT NULL, PRIMARY KEY(negotiation_id,revision));
CREATE TABLE offers (id text PRIMARY KEY, data jsonb NOT NULL, negotiation_id text GENERATED ALWAYS AS (data->>'negotiationId') STORED REFERENCES negotiations(id));
CREATE TABLE demo_holds (id text PRIMARY KEY, request_id text UNIQUE NOT NULL REFERENCES rental_requests(id), negotiation_id text UNIQUE NOT NULL REFERENCES negotiations(id), item_id text NOT NULL REFERENCES items(id), start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, status text NOT NULL CHECK(status IN ('ACTIVE','EXPIRED','RELEASED')), CHECK(start_at < end_at), EXCLUDE USING gist (item_id WITH =, tstzrange(start_at,end_at,'[)') WITH &&) WHERE(status='ACTIVE'));
CREATE TABLE agent_tasks (id text PRIMARY KEY, data jsonb NOT NULL, request_id text GENERATED ALWAYS AS (data->>'requestId') STORED REFERENCES rental_requests(id), actor_user_id text NOT NULL REFERENCES users(id), context jsonb NOT NULL DEFAULT '{}', result jsonb, created_at timestamptz NOT NULL);
CREATE TABLE task_effects (task_id text REFERENCES agent_tasks(id), step text NOT NULL, input_hash text NOT NULL, created_at timestamptz NOT NULL, PRIMARY KEY(task_id,step,input_hash));
CREATE TABLE outbox (id bigserial PRIMARY KEY, kind text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL, delivered_at timestamptz, attempts integer NOT NULL DEFAULT 0);
CREATE INDEX outbox_pending ON outbox(id) WHERE delivered_at IS NULL;
CREATE TABLE user_events (user_id text REFERENCES users(id), cursor bigint NOT NULL, data jsonb NOT NULL, occurred_at timestamptz NOT NULL, PRIMARY KEY(user_id,cursor));
CREATE INDEX events_retention ON user_events(occurred_at);
CREATE TABLE idempotency_records (session_id text REFERENCES sessions(id), method text NOT NULL, path text NOT NULL, key text NOT NULL, actor_user_id text NOT NULL REFERENCES users(id), body_hash text NOT NULL, response jsonb NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(session_id,method,path,key));
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable record'; END $$;
CREATE TRIGGER quotes_immutable BEFORE UPDATE ON pricing_quotes FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER terms_immutable BEFORE UPDATE ON terms_revisions FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER offers_immutable BEFORE UPDATE ON offers FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE TRIGGER need_immutable BEFORE UPDATE ON request_need_revisions FOR EACH ROW EXECUTE FUNCTION immutable_record();
